		t.Fatalf("结束不存在的班次应返回 NotFoundError，得到 %v", err)
	}
	if _, _, err := s.CreateHandover(1, 2); !isNotFound(err) {
		t.Fatalf("不存在的班次发起交接应返回 NotFoundError，得到 %v", err)
	}
}

