func TestResubmitAfterReturn(t *testing.T) {
	s, _, _, h, it := setupHandover(t)
	if err := s.HandoverReturn(h.ID, it.ID, "王五", "情况不符"); err != nil {
		t.Fatal(err)
	}
	// 交班人追加说明重新提交
