	i2, _ := s.AddItem(from.ID, "事项二", SeverityNormal, "", "李四")
	i3, _ := s.AddItem(from.ID, "事项三", SeverityNormal, "", "李四")
	if err := s.EndShift(from.ID); err != nil {
		t.Fatal(err)
	}
	to := makeShift(t, s, "值班", "李四", cst(2, 16), cst(3, 0), "")
	h, _, err := s.CreateHandover(from.ID, to.ID)
