		t.Fatal(err)
	}
	if err := s.HandoverReturn(h.ID, i2.ID, "王五", "原因"); err != nil {
		t.Fatal(err)
	}
	h2, _ := s.GetHandover(h.ID)
	if h2.Complete {
		t.Fatal("存在待处理和退回项时不应完成")
