	}
	hi := h.FindItem(itemID)
	if hi == nil {
		return &NotFoundError{What: fmt.Sprintf("交接记录 #%d 中的事项", handoverID), ID: itemID}
	}
	it, err := s.GetItem(itemID)
	if err != nil {
		return err
	}
	if err := fn(h, hi, it); err != nil {
		return err
	}
	hi.HandledAt = now()
	h.recompute()
	return s.save()
}

// HandoverReceive 接班人确认接收某项事项。
